/**
 * @vitest-environment node
 *
 * Settlement push regression (pilot item P0-2).
 *
 * Offline settlements are stored locally under a Dexie auto-increment key, so
 * the push payload carries only the local `id`; the server mapper turns it into
 * `local_id` and never sends a primary key. This suite pins the two database
 * facts that make that safe, and the route behaviour that depends on them:
 *
 *   1. `settlements.id` is generated by the database (has a default), and
 *   2. `(device_id, local_id)` is UNIQUE, so a re-delivered row can never
 *      insert a second copy.
 *
 * No Postgres exists on this machine, so the fake executor below is built from
 * the real drizzle table metadata (lib/db/src/schema) and enforces what the DDL
 * declares: NOT NULL without a default, primary keys and UNIQUE constraints.
 * Statements that Postgres would reject throw an error carrying the SQLSTATE,
 * and a failed transaction restores the pre-transaction rows.
 */
process.env.JWT_SECRET = "test-secret-for-unit-tests";
process.env.APP_BASE_URL = "http://localhost:3000";

import { describe, it, expect, vi, beforeEach } from "vitest";
import { getTableColumns, getTableName } from "drizzle-orm";
import { getTableConfig } from "drizzle-orm/pg-core";
import { settlements, devices, businessMembers } from "@workspace/db/schema";

// ─── Fake executor (hoisted: @workspace/db must resolve to it) ───────────────

const { state, fakeDb } = vi.hoisted(() => {
  const state = {
    rows: new Map<string, any[]>(),
    seq: new Map<string, number>(),
    cols: new WeakMap<object, { tsKey: string; name: string; col: any }[]>(),
    uniques: new WeakMap<object, { name: string; cols: string[] }[]>(),
  };
  const api: any = { state };

  function pgError(code: string, message: string) {
    return Object.assign(new Error(message), { code });
  }

  api.pgError = pgError;
  api.tableRows = (name: string) => {
    if (!state.rows.has(name)) state.rows.set(name, []);
    return state.rows.get(name)!;
  };
  api.cols = (table: any) => {
    let cached = state.cols.get(table);
    if (!cached) {
      cached = Object.entries(getTableColumns(table)).map(([tsKey, col]: [string, any]) => ({
        tsKey, name: col.name, col,
      }));
      state.cols.set(table, cached);
    }
    return cached;
  };
  api.uniq = (table: any) => {
    let cached = state.uniques.get(table);
    if (!cached) {
      cached = getTableConfig(table).uniqueConstraints.map((u: any) => ({
        name: u.name, cols: u.columns.map((c: any) => c.name),
      }));
      state.uniques.set(table, cached);
    }
    return cached;
  };

  api.toRow = (table: any, values: any) => {
    const row: any = {};
    for (const { tsKey, name, col } of api.cols(table)) {
      let value = values[tsKey];
      if (value === undefined) {
        if (/Serial/.test(String(col.columnType || ""))) {
          const next = (state.seq.get(name) || 0) + 1;
          state.seq.set(name, next);
          value = next;
        } else if (col.hasDefault) {
          value = typeof col.default === "function" ? col.default() : col.default;
        } else if (col.notNull) {
          throw pgError("23502", `null value in column "${name}" of relation "${getTableName(table)}" violates not-null constraint`);
        } else {
          value = null;
        }
      }
      row[name] = value;
    }
    return row;
  };

  api.checkConstraints = (table: any, row: any) => {
    const name = getTableName(table);
    const rows = api.tableRows(name);
    for (const u of api.uniq(table)) {
      if (u.cols.some((c) => row[c] === null || row[c] === undefined)) continue;
      if (rows.some((r) => u.cols.every((c) => r[c] === row[c]))) {
        throw pgError("23505", `duplicate key value violates unique constraint "${u.name}"`);
      }
    }
    const pk = api.cols(table).filter((c) => c.col.primary).map((c) => c.name);
    if (pk.length > 0 && rows.some((r) => pk.every((c) => r[c] === row[c]))) {
      throw pgError("23505", `duplicate key value violates unique constraint "${name}_pkey"`);
    }
  };

  api.project = (row: any, table: any, fields?: any) => {
    if (!fields) {
      const out: any = {};
      for (const { tsKey, name } of api.cols(table)) out[tsKey] = row[name] ?? null;
      return out;
    }
    const out: any = {};
    for (const [key, field] of Object.entries(fields) as [string, any]) {
      const col = field && typeof field === "object" && typeof field.name === "string" ? field : null;
      out[key] = col ? (row[col.name] ?? null) : undefined;
    }
    return out;
  };

  api.matches = (row: any, pred: any): boolean => {
    if (!pred) return true;
    if (pred.kind === "and") return pred.parts.every((p: any) => api.matches(row, p));
    if (pred.kind === "or") return pred.parts.some((p: any) => api.matches(row, p));
    const actual = row[pred.col?.name];
    if (pred.kind === "eq") return actual === pred.val || String(actual) === String(pred.val);
    if (pred.kind === "gt") return Number(actual) > Number(pred.val);
    if (pred.kind === "in") return pred.vals.map(String).includes(String(actual));
    return true;
  };

  api.fakeDb = {
    select(fields?: any) {
      let rows: any[] = [];
      let table: any = null;
      const q: any = {
        from(t: any) {
          table = t;
          rows = api.tableRows(getTableName(t)).map((r) => ({ ...r }));
          return q;
        },
        where(pred: any) {
          rows = rows.filter((r) => api.matches(r, pred));
          return q;
        },
        orderBy() { return q; },
        limit(n: number) {
          return Promise.resolve(rows.slice(0, n).map((r) => api.project(r, table, fields)));
        },
        then(resolve: any, reject: any) {
          return Promise.resolve(rows.map((r) => api.project(r, table, fields))).then(resolve, reject);
        },
      };
      return q;
    },
    insert(table: any) {
      const name = getTableName(table);
      return {
        values(values: any) {
          const list = Array.isArray(values) ? values : [values];
          let done: any[] | null = null;
          const run = () => {
            if (done) return done;
            done = [];
            for (const item of list) {
              const row = api.toRow(table, item);
              api.checkConstraints(table, row);
              api.tableRows(name).push(row);
              done.push(row);
            }
            return done;
          };
          return {
            onConflictDoUpdate({ target, set }: any) {
              const targets = (Array.isArray(target) ? target : [target]).map((c: any) => c.name);
              for (const item of list) {
                const row = api.toRow(table, item);
                const existing = api.tableRows(name).find((r) => targets.every((c) => r[c] === row[c]));
                if (existing) Object.assign(existing, api.toRow(table, set));
                else {
                  api.checkConstraints(table, row);
                  api.tableRows(name).push(row);
                }
              }
              return Promise.resolve([]);
            },
            returning(fields?: any) {
              return Promise.resolve(run().map((r) => api.project(r, table, fields)));
            },
            then(resolve: any, reject: any) {
              return Promise.resolve(run()).then(resolve, reject);
            },
          };
        },
      };
    },
    update(table: any) {
      let values: any = null;
      const q: any = {
        set(v: any) { values = v; return q; },
        where(pred: any) {
          const rows = api.tableRows(getTableName(table));
          const patch: any = {};
          for (const { tsKey, name } of api.cols(table)) {
            if (values[tsKey] !== undefined) patch[name] = values[tsKey];
          }
          let changed = 0;
          for (let i = 0; i < rows.length; i++) {
            if (!api.matches(rows[i], pred)) continue;
            rows[i] = { ...rows[i], ...patch };
            changed++;
          }
          return Promise.resolve(changed);
        },
        then(resolve: any, reject: any) {
          return Promise.resolve(0).then(resolve, reject);
        },
      };
      return q;
    },
    transaction(fn: any) {
      const snapshot = new Map<string, any[]>();
      for (const [name, rows] of state.rows) snapshot.set(name, rows.map((r) => ({ ...r })));
      try {
        return Promise.resolve(fn(api.fakeDb)).catch((err) => {
          state.rows = snapshot;
          throw err;
        });
      } catch (err) {
        state.rows = snapshot;
        throw err;
      }
    },
  };

  return { state, fakeDb: api.fakeDb };
});

// drizzle's predicate builders are replaced by plain descriptors the fake
// executor can evaluate; everything else (sql, schema builders) is untouched.
vi.mock("drizzle-orm", async (importOriginal) => {
  const actual: any = await importOriginal();
  return {
    ...actual,
    eq: (col: any, val: any) => ({ kind: "eq", col, val }),
    and: (...parts: any[]) => ({ kind: "and", parts: parts.filter(Boolean) }),
    or: (...parts: any[]) => ({ kind: "or", parts: parts.filter(Boolean) }),
    gt: (col: any, val: any) => ({ kind: "gt", col, val }),
    inArray: (col: any, vals: any[]) => ({ kind: "in", col, vals }),
    asc: (col: any) => ({ kind: "asc", col }),
  };
});

vi.mock("@workspace/db", () => ({
  db: fakeDb,
  requireDb: vi.fn(() => fakeDb),
  customerBalanceExpression: vi.fn(() => ({ kind: "sql" })),
}));

vi.mock("jsonwebtoken", () => ({
  default: { sign: vi.fn(), verify: vi.fn() },
}));

vi.mock("../auth.js", () => ({
  verifyJwt: vi.fn().mockReturnValue({ userId: 1 }),
}));

vi.mock("../rateLimits.js", () => ({
  syncRateLimiter: (_req: any, _res: any, next: any) => next(),
}));

vi.mock("../rbac.js", () => ({
  requirePermission: () => (_req: any, _res: any, next: any) => next(),
}));

vi.mock("../services/pushNotificationSender.js", () => ({ sendPushToOwner: vi.fn() }));
vi.mock("../services/reminderConfiguration.js", () => ({ setLastReminderSentAt: vi.fn() }));
vi.mock("../services/reminderHistory.js", () => ({ createHistoryEntry: vi.fn() }));
vi.mock("../services/telegramBotService.js", () => ({ sendTelegramTextMessage: vi.fn() }));
vi.mock("../services/notificationPreferences.js", () => ({
  getPreferencesForBusiness: vi.fn().mockResolvedValue(null),
  shouldNotify: vi.fn(() => true),
  isInQuietHours: vi.fn(() => false),
}));

import syncRouter from "../sync.js";

// ─── Helpers ────────────────────────────────────────────────────────────────

const DEVICE_ID = "device-a";

const SETTLEMENT_ROW = {
  id: 1,
  settlement_id: "settle_1763700000000_abcd1234",
  staff_id: 7,
  period_start: 1763690000000,
  period_end: 1763700000000,
  expected_cash: 500,
  actual_cash: 480,
  cash_variance: -20,
  expected_transfer: 0,
  actual_transfer: 0,
  transfer_variance: 0,
  expected_total: 500,
  actual_total: 480,
  total_variance: -20,
  adjustments: [],
  final_expected_cash: 500,
  final_expected_total: 500,
  final_variance: -20,
  status: "checked",
  notes: null,
  settled_at: 1763700000000,
  settled_by: 7,
  reconciled_at: null,
  reconciled_by: null,
  reconciliation_note: null,
  created_at: 1763700000000,
  updated_at: 1763700000000,
  reconciliation_status: "staff_submitted",
  staff_reported_cash: 480,
  staff_reported_transfer: 0,
  staff_submitted_at: 1763700000000,
  staff_note: "evening close",
  owner_confirmed_cash: null,
  owner_confirmed_transfer: null,
  owner_note: null,
  reconciliation_log: [{ stage: "staff", actor: "Staff", at: 1763700000000, note: "submitted" }],
  carry_forward: null,
  sync_version: 1,
  schema_version: 1,
  device_id: DEVICE_ID,
  business_id: 1,
};

function seedDeviceAndMember() {
  state.rows.set("devices", [{
    id: 1, user_id: 1, device_id: DEVICE_ID, token_hash: "hash", staff_id: null,
  }]);
  state.rows.set("business_members", [{
    id: 1, business_id: 1, user_id: 1, role: "owner", active: true,
  }]);
}

function findHandler(method: string, path: string) {
  const stack = (syncRouter as any).stack;
  const layer = stack.find((l: any) => l.route?.path === path && l.route?.methods?.[method]);
  if (!layer) throw new Error(`${method.toUpperCase()} ${path} not found`);
  return layer.route.stack[layer.route.stack.length - 1].handle;
}

function makeReq(overrides: any = {}) {
  return {
    method: "POST", url: "/push", body: {}, query: {},
    headers: { authorization: "Bearer valid-token", "x-business-id": "1" },
    params: {}, ...overrides,
  } as any;
}

function makeRes() {
  const res: any = {};
  res.statusCode = 200;
  res.status = vi.fn(function (code: number) { res.statusCode = code; return res; });
  res.json = vi.fn(function (payload: any) { res.body = payload; return res; });
  return res;
}

async function push(rows: any[]) {
  const handler = findHandler("post", "/push");
  const req = makeReq({ body: { device_id: DEVICE_ID, tables: rows.length ? { settlements: rows } : {} } });
  const res = makeRes();
  const noop = () => {};
  await handler(req, res, noop);
  return res;
}

const settlementRows = () => state.rows.get("settlements") || [];

beforeEach(() => {
  state.rows = new Map();
  state.seq = new Map();
  seedDeviceAndMember();
});

// ─── Schema contract ────────────────────────────────────────────────────────

describe("settlements schema contract", () => {
  const columns = Object.entries(getTableColumns(settlements)) as [string, any][];

  it("generates settlements.id in the database instead of requiring the client to send it", () => {
    const id = columns.find(([key]) => key === "id")![1];
    expect(id.notNull).toBe(true);
    expect(id.hasDefault).toBe(true);
  });

  it("makes (device_id, local_id) unique, the pair the pusher looks rows up by", () => {
    const uniques = getTableConfig(settlements).uniqueConstraints.map((u: any) =>
      u.columns.map((c: any) => c.name).sort());
    expect(uniques).toContainEqual(["device_id", "local_id"]);
  });

});

// ─── Route behaviour ────────────────────────────────────────────────────────

describe("POST /api/sync/push with an offline settlement", () => {
  it("stores the settlement once, with a server-generated id", async () => {
    const res = await push([SETTLEMENT_ROW]);

    expect(res.statusCode).toBe(200);
    expect(res.body.results?.settlements?.count).toBe(1);

    const stored = settlementRows();
    expect(stored).toHaveLength(1);
    expect(stored[0].local_id).toBe(1);
    expect(stored[0].device_id).toBe(DEVICE_ID);
    expect(typeof stored[0].id).toBe("number");
    expect(stored[0].id).toBeGreaterThan(0);
  });

  it("carries the settlement review fields the owner writes on the other phone", async () => {
    await push([SETTLEMENT_ROW]);

    const stored = settlementRows()[0];
    expect(stored.reconciliation_status).toBe("staff_submitted");
    expect(stored.staff_reported_cash).toBe(480);
    expect(stored.staff_note).toBe("evening close");
    expect(stored.reconciliation_log).toEqual(SETTLEMENT_ROW.reconciliation_log);
  });

  it("applies the same row twice without duplicating it and without reporting a conflict", async () => {
    // A push whose acknowledgement was lost is retried with the identical row.
    await push([SETTLEMENT_ROW]);
    const res = await push([SETTLEMENT_ROW]);

    expect(res.statusCode).toBe(200);
    expect(res.body.results?.settlements?.count).toBe(1);
    expect(res.body.conflicts ?? []).toHaveLength(0);
    expect(settlementRows()).toHaveLength(1);
    expect(settlementRows()[0].id).toBe(settlementRows()[0].id);
  });

  it("still reports a genuine conflict when the same version arrives with different values", async () => {
    await push([SETTLEMENT_ROW]);
    const res = await push([{ ...SETTLEMENT_ROW, actual_cash: 470, cash_variance: -30 }]);

    expect(res.statusCode).toBe(200);
    expect(res.body.results?.settlements?.conflicts).toBe(1);
    expect(settlementRows()).toHaveLength(1);
    expect(settlementRows()[0].actual_cash).toBe(480);
  });

  it("reports a conflict when a stale device pushes an older version", async () => {
    await push([SETTLEMENT_ROW]);
    await push([{ ...SETTLEMENT_ROW, sync_version: 2, updated_at: 1763700500000 }]);
    const res = await push([{ ...SETTLEMENT_ROW, actual_cash: 470, updated_at: 1763700900000 }]);

    expect(res.statusCode).toBe(200);
    expect(res.body.results?.settlements?.conflicts).toBe(1);
    expect(settlementRows()[0].actual_cash).toBe(480);
  });

  it("does not let a rejected settlement silently drop the rest of the push", async () => {
    // Every table shares one transaction: before the fix a single settlement
    // (no id default) rolled the whole push back, so sales stopped syncing too.
    const handler = findHandler("post", "/push");
    const req = makeReq({
      body: {
        device_id: DEVICE_ID,
        tables: {
          transactions: [{
            id: 11, device_id: DEVICE_ID, transaction_id: "tx-11", type: "sale",
            amount: 120, item_name: "Sugar", cost_price: 100, quantity: 1,
            created_at: 1763700000000, updated_at: 1763700000000, business_id: 1,
          }],
          settlements: [SETTLEMENT_ROW],
        },
      },
    });
    const res = makeRes();
    await handler(req, res, () => {});

    expect(res.statusCode).toBe(200);
    expect(res.body.results?.transactions?.count).toBe(1);
    expect(res.body.results?.settlements?.count).toBe(1);
    expect((state.rows.get("transactions") || [])).toHaveLength(1);
    expect(settlementRows()).toHaveLength(1);
  });
});

// `devices` and `businessMembers` are only read by the fake for auth, but the
// push also selects the owner for notifications — keep the assertion honest
// that a device-less seed is not what these tests rely on.
describe("push authentication", () => {
  it("links a device the first time it is seen", async () => {
    state.rows.set("devices", []);
    expect((await push([])).statusCode).toBe(200);
    expect((state.rows.get("devices") || [])[0].device_id).toBe(DEVICE_ID);
  });
});

